import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong(), k = (int) nextLong();
        HashMap<Long, Integer> counts = new HashMap<>();
        int best = 0;
        for (int i = 0; i < n; i++) best = Math.max(best, counts.merge(nextLong(), 1, Integer::sum));
        // the whole array is optimal whenever any value occurs more than k times
        System.out.println(best > k ? n : 0);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, k := next(), next()
	counts := make(map[int]int, n)
	best := 0
	for i := 0; i < n; i++ {
		x := next()
		counts[x]++
		best = max(best, counts[x])
	}
	// the whole array is optimal whenever any value occurs more than k times
	if best > k {
		fmt.Println(n)
	} else {
		fmt.Println(0)
	}
}
